SELECT  FROM lab_trade_product

 AND product_name LIKE CONCAT('%',#{keyword},'%')
 AND category=#{category}
 AND brand_id IN #{brandId}
 AND price >= #{minimum}
 AND price <= #{maximum}

ORDER BY price DESC,idORDER BY id

